import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { toast } from 'react-toastify';
import { userAPI } from '../../services/api';
import { getUser } from '../../utils/auth';

const UserDashboard = () => {
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0
  });
  const [recentBookings, setRecentBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [greeting, setGreeting] = useState('');
  const user = getUser();

  useEffect(() => {
    fetchDashboardData();
    setGreetingMessage();
  }, []);

  const setGreetingMessage = () => {
    const hour = new Date().getHours();
    if (hour < 12) setGreeting('Selamat Pagi');
    else if (hour < 17) setGreeting('Selamat Siang');
    else setGreeting('Selamat Malam');
  };

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      console.log('🔍 Fetching user dashboard data...');
      const response = await userAPI.getMyBookings();
      console.log('📊 User dashboard API response:', response);
      
      // Handle nested response structure
      let bookings = response.data;
      if (response.data && response.data.data) {
        bookings = response.data.data;
      }
      
      console.log('📋 Bookings data:', bookings);
      
      // Ensure bookings is an array
      if (!Array.isArray(bookings)) {
        console.warn('⚠️ Bookings is not an array, setting to empty array');
        bookings = [];
      }

      // Calculate stats
      const stats = {
        total: bookings.length,
        pending: bookings.filter(b => b.status === 'pending').length,
        approved: bookings.filter(b => b.status === 'approved').length,
        rejected: bookings.filter(b => b.status === 'rejected').length
      };

      setStats(stats);
      setRecentBookings(bookings.slice(0, 5)); // Show last 5 bookings
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
      toast.error('Gagal memuat data dashboard');
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      pending: {
        bg: 'bg-yellow-100 text-yellow-800 border-yellow-200',
        icon: '⏳',
        text: 'MENUNGGU'
      },
      approved: {
        bg: 'bg-green-100 text-green-800 border-green-200',
        icon: '✅',
        text: 'DISETUJUI'
      },
      rejected: {
        bg: 'bg-red-100 text-red-800 border-red-200',
        icon: '❌',
        text: 'DITOLAK'
      }
    };

    const config = statusConfig[status] || statusConfig.pending;
    
    return (
      <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium border ${config.bg}`}>
        <span className="mr-1">{config.icon}</span>
        {config.text}
      </span>
    );
  };

  const getRequestTypeBadge = (type) => {
    const typeConfig = {
      meeting: { bg: 'bg-blue-100 text-blue-800', icon: '👥', text: 'Meeting' },
      event: { bg: 'bg-purple-100 text-purple-800', icon: '🎉', text: 'Event' },
      training: { bg: 'bg-orange-100 text-orange-800', icon: '📚', text: 'Training' },
      presentation: { bg: 'bg-indigo-100 text-indigo-800', icon: '📊', text: 'Presentation' }
    };

    const config = typeConfig[type] || { bg: 'bg-gray-100 text-gray-800', icon: '📝', text: type };
    
    return (
      <span className={`inline-flex items-center px-2 py-1 rounded-md text-xs font-medium ${config.bg}`}>
        <span className="mr-1">{config.icon}</span>
        {config.text}
      </span>
    );
  };

  const StatCard = ({ icon, title, value, subtitle, color, trend }) => (
    <div className="bg-white rounded-2xl p-6 shadow-lg hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 border border-gray-100">
      <div className="flex items-center justify-between">
        <div>
          <div className={`inline-flex items-center justify-center w-12 h-12 rounded-xl ${color} mb-4`}>
            <span className="text-2xl">{icon}</span>
          </div>
          <h3 className="text-2xl font-bold text-gray-900 mb-1">{value}</h3>
          <p className="text-sm text-gray-600">{subtitle}</p>
          {trend && (
            <div className="flex items-center mt-2">
              <span className="text-xs text-green-600 font-medium">
                ↗️ {trend}% dari bulan lalu
              </span>
            </div>
          )}
        </div>
        <div className="text-right">
          <h2 className="text-lg font-semibold text-gray-700">{title}</h2>
        </div>
      </div>
    </div>
  );

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-500 border-t-transparent mb-4"></div>
          <p className="text-gray-600 font-medium">Memuat dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
      {/* Header Section */}
      <div className="bg-white border-b border-gray-200 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between">
            <div className="mb-4 sm:mb-0">
              <div className="flex items-center">
                <div className="w-12 h-12 bg-gradient-to-r from-blue-500 to-purple-600 rounded-xl flex items-center justify-center mr-4">
                  <span className="text-white text-xl">👋</span>
                </div>
                <div>
                  <h1 className="text-2xl font-bold text-gray-900">{greeting}!</h1>
                  <p className="text-gray-600">{user?.name || user?.email}</p>
                </div>
              </div>
            </div>
            <div className="flex space-x-3">
              <Link
                to="/user/booking"
                className="inline-flex items-center px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white font-semibold rounded-xl transition-all duration-300 transform hover:scale-105 shadow-lg hover:shadow-xl"
              >
                <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                </svg>
                Buat Booking Baru
              </Link>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <StatCard
            icon="📅"
            title="Total Booking"
            value={stats.total}
            subtitle="Semua booking"
            color="bg-blue-100"
            trend={12}
          />
          <StatCard
            icon="⏳"
            title="Menunggu"
            value={stats.pending}
            subtitle="Pending approval"
            color="bg-yellow-100"
          />
          <StatCard
            icon="✅"
            title="Disetujui"
            value={stats.approved}
            subtitle="Booking sukses"
            color="bg-green-100"
            trend={8}
          />
          <StatCard
            icon="❌"
            title="Ditolak"
            value={stats.rejected}
            subtitle="Perlu revisi"
            color="bg-red-100"
          />
        </div>

        {/* Recent Bookings Section */}
        <div className="bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden">
          <div className="bg-gradient-to-r from-blue-600 to-purple-600 px-6 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center">
                <span className="text-white text-2xl mr-3">📋</span>
                <h2 className="text-xl font-bold text-white">Booking Terbaru</h2>
              </div>
              <Link
                to="/user/mybookings"
                className="inline-flex items-center px-4 py-2 bg-white bg-opacity-20 hover:bg-opacity-30 text-white rounded-lg transition-all duration-200 text-sm font-medium"
              >
                Lihat Semua
                <svg className="w-4 h-4 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                </svg>
              </Link>
            </div>
          </div>

          <div className="p-6">
            {recentBookings.length > 0 ? (
              <div className="space-y-4">
                {recentBookings.map((booking, index) => (
                  <div 
                    key={booking.id} 
                    className="bg-gray-50 rounded-xl p-4 hover:bg-gray-100 transition-colors duration-200 border border-gray-200"
                  >
                    <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between">
                      <div className="flex-1">
                        <h3 className="font-semibold text-gray-900 mb-2">{booking.title}</h3>
                        <div className="flex flex-wrap items-center gap-4 text-sm text-gray-600">
                          <div className="flex items-center">
                            <svg className="w-4 h-4 mr-1 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                            </svg>
                            {new Date(booking.date).toLocaleDateString('id-ID')}
                          </div>
                          <div className="flex items-center">
                            <svg className="w-4 h-4 mr-1 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                            {booking.start_time} - {booking.end_time}
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center space-x-3 mt-3 lg:mt-0">
                        {getRequestTypeBadge(booking.request_type)}
                        {getStatusBadge(booking.status)}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-12">
                <div className="w-24 h-24 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <span className="text-4xl">📅</span>
                </div>
                <h3 className="text-lg font-semibold text-gray-900 mb-2">Belum Ada Booking</h3>
                <p className="text-gray-600 mb-6">Mulai dengan membuat booking pertama Anda</p>
                <Link
                  to="/user/booking"
                  className="inline-flex items-center px-6 py-3 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white font-semibold rounded-xl transition-all duration-300 transform hover:scale-105 shadow-lg"
                >
                  <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                  </svg>
                  Buat Booking Pertama
                </Link>
              </div>
            )}
          </div>
        </div>

        {/* Quick Actions */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-8">
          <Link
            to="/user/mybookings"
            className="bg-white rounded-xl p-6 shadow-lg hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 border border-gray-100 group"
          >
            <div className="flex items-center">
              <div className="w-12 h-12 bg-blue-100 rounded-xl flex items-center justify-center mr-4 group-hover:bg-blue-200 transition-colors duration-200">
                <span className="text-2xl">📝</span>
              </div>
              <div>
                <h3 className="font-semibold text-gray-900">My Bookings</h3>
                <p className="text-sm text-gray-600">Kelola semua booking</p>
              </div>
            </div>
          </Link>

          <Link
            to="/user/profile"
            className="bg-white rounded-xl p-6 shadow-lg hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 border border-gray-100 group"
          >
            <div className="flex items-center">
              <div className="w-12 h-12 bg-purple-100 rounded-xl flex items-center justify-center mr-4 group-hover:bg-purple-200 transition-colors duration-200">
                <span className="text-2xl">👤</span>
              </div>
              <div>
                <h3 className="font-semibold text-gray-900">Profile</h3>
                <p className="text-sm text-gray-600">Edit informasi akun</p>
              </div>
            </div>
          </Link>

          <Link
            to="/user/history"
            className="bg-white rounded-xl p-6 shadow-lg hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 border border-gray-100 group"
          >
            <div className="flex items-center">
              <div className="w-12 h-12 bg-green-100 rounded-xl flex items-center justify-center mr-4 group-hover:bg-green-200 transition-colors duration-200">
                <span className="text-2xl">📊</span>
              </div>
              <div>
                <h3 className="font-semibold text-gray-900">History</h3>
                <p className="text-sm text-gray-600">Riwayat aktivitas</p>
              </div>
            </div>
          </Link>
        </div>
      </div>
    </div>
  );
};

export default UserDashboard;
